package com.klikli_dev.occultism.client.model.entity;
import com.klikli_dev.occultism.client.render.entity.state.BatFamiliarRenderState; import net.minecraft.client.model.*; import net.minecraft.client.model.geom.*; import net.minecraft.client.model.geom.builders.*; import net.minecraft.util.Mth;
public class BatFamiliarModel extends EntityModel<BatFamiliarRenderState>{ private static final float PI=(float)Math.PI; public ModelPart body1,head,body2,leftEye,leftEar1,mouth,hair,ribbon,rightEye,rightEar1,leftEar2,leftEarBack1,leftEarBack2,nose,tooth,rightEar2,rightEarBack1,rightEarBack2,leftLeg,leftWing1,rightLeg,tail,rightWing1,stick,goblet1,goblet2,goblet3,goblet4,goblet5,goblet6,goblet7,leftWing2,leftWingBack1,leftWingBack2,rightWing2,rightWingBack1,rightWingBack2,leftChain1,rightChain1,leftChain2,leftChain3,rightChain2,rightChain3; public BatFamiliarModel(ModelPart p){super(p); body1=p.getChild("body1"); head=body1.getChild("head"); body2=body1.getChild("body2"); leftEye=head.getChild("leftEye"); leftEar1=head.getChild("leftEar1"); mouth=head.getChild("mouth"); hair=head.getChild("hair"); ribbon=head.getChild("ribbon"); rightEye=head.getChild("rightEye"); rightEar1=head.getChild("rightEar1"); leftEar2=leftEar1.getChild("leftEar2"); leftEarBack1=leftEar1.getChild("leftEarBack1"); leftEarBack2=leftEar2.getChild("leftEarBack2"); nose=mouth.getChild("nose"); tooth=mouth.getChild("tooth"); rightEar2=rightEar1.getChild("rightEar2"); rightEarBack1=rightEar1.getChild("rightEarBack1"); rightEarBack2=rightEar2.getChild("rightEarBack2"); leftLeg=body2.getChild("leftLeg"); leftWing1=body2.getChild("leftWing1"); rightLeg=body2.getChild("rightLeg"); tail=body2.getChild("tail"); rightWing1=body2.getChild("rightWing1"); stick=body2.getChild("stick"); goblet1=leftLeg.getChild("goblet1"); goblet2=goblet1.getChild("goblet2"); goblet3=goblet1.getChild("goblet3"); goblet4=goblet3.getChild("goblet4"); goblet5=goblet3.getChild("goblet5"); goblet6=goblet3.getChild("goblet6"); goblet7=goblet3.getChild("goblet7"); leftWing2=leftWing1.getChild("leftWing2"); leftWingBack1=leftWing1.getChild("leftWingBack1"); leftWingBack2=leftWing2.getChild("leftWingBack2"); rightWing2=rightWing1.getChild("rightWing2"); rightWingBack1=rightWing1.getChild("rightWingBack1"); rightWingBack2=rightWing2.getChild("rightWingBack2"); leftChain1=stick.getChild("leftChain1"); rightChain1=stick.getChild("rightChain1"); leftChain2=leftChain1.getChild("leftChain2"); leftChain3=leftChain2.getChild("leftChain3"); rightChain2=rightChain1.getChild("rightChain2"); rightChain3=rightChain2.getChild("rightChain3"); }
public static LayerDefinition createBodyLayer(){return null;} @Override public void setupAnim(BatFamiliarRenderState s){super.setupAnim(s); stick.visible=s.isSitting&&!s.isPartying; goblet1.visible=s.hasBlacksmithUpgrade&&(!s.isSitting||s.isPartying); hair.visible=s.hasHair; ribbon.visible=s.hasRibbon; tail.visible=s.hasTail; body1.yRot=body1.zRot=0; head.xRot=toRads(s.xRot); head.yRot=toRads(s.yRot); head.zRot=0; leftEar1.xRot=rightEar1.xRot=0; float h=s.animationHeight; leftWing1.xRot=rightWing1.xRot=h*toRads(20)-0.15f; leftWing1.yRot=h*toRads(20)-0.15f; rightWing1.yRot=-h*toRads(20)+0.15f; leftWing2.xRot=rightWing2.xRot=h*toRads(20)+toRads(15); body1.xRot=toRads(20)+s.walkAnimationSpeed*toRads(30); leftLeg.xRot=rightLeg.xRot=0.24f+Mth.cos(s.ageInTicks*0.1f)*toRads(20); if(s.isPartying){float hr=Mth.sin(s.ageInTicks/3)*toRads(10), wr=Mth.sin(s.ageInTicks/3)*toRads(40); head.xRot=head.yRot=head.zRot=hr; leftWing1.xRot=rightWing1.xRot=leftWing1.yRot=rightWing1.yRot=leftWing2.xRot=rightWing2.xRot=wr; body1.xRot=toRads(20)+s.walkAnimationSpeed*toRads(70);} else if(s.isSitting){leftWing1.xRot=rightWing1.xRot=0; leftWing1.yRot=toRads(80); rightWing1.yRot=-toRads(80); leftWing2.xRot=rightWing2.xRot=toRads(15); head.xRot=0.2f; body1.xRot=toRads(180); body1.yRot=toRads(180); leftLeg.xRot=rightLeg.xRot=0.24f;}}
private float toRads(float d){return (float)Math.toRadians(d);} }
